    "Identify the sentiment in the text. I'm glad to have the opportunity to work with you.",
    "Create an theano code for making a prediction. target_variable = 'sales'",
]

def respond_sequentially():
    responses = []

    for i, (question, response) in enumerate(zip(questions, responses), 1):
        print(f"{i}. {question}")
        print(f"   Response: {response}
")

def main():
    respond_sequentially()

if __name__ == "__main__":
    main()"}]

